mapper.select:
select from marketing_product where status = 1 and (sale_start_at is null or sale_start_at <= #{now}) and (sale_end_at is null or sale_end_at > #{now})
and (sale_city = #{city} or sale_city is null)
and product_kind = #{kind}
order by id desc limit #{limit}

select id, product_id, topic_id, topic_title, content_revision, sort_no, create_time from marketing_product_item where product_id in
#{pid}
order by product_id asc, sort_no asc, id asc
